import React, { useEffect, useRef, useState } from 'react';
import { Users, Target, Zap, Award, Linkedin, Github, Mail } from 'lucide-react';

const teamMembers = [
  {
    name: 'Ruben Albao',
    role: 'Project Lead & Backend Developer',
    description: 'Expert in PHP, MySQL, and system architecture. Leads the technical direction of projects.',
    gradient: 'from-blue-500 to-cyan-500',
    initials: 'RA',
    socials: { linkedin: '#', github: '#', email: 'mailto:ruben@projectmun.com' }
  },
  {
    name: 'Kristian Gomez',
    role: 'Frontend Developer',
    description: 'Specialized in React.js and modern JavaScript. Creates responsive and interactive user interfaces.',
    gradient: 'from-purple-500 to-pink-500',
    initials: 'KG',
    socials: { linkedin: '#', github: '#', email: 'mailto:kristian@projectmun.com' }
  },
  {
    name: 'Jonelle Mayari',
    role: 'UI/UX Designer',
    description: 'Creative designer focused on user experience and modern interface design principles.',
    gradient: 'from-orange-500 to-red-500',
    initials: 'JM',
    socials: { linkedin: '#', github: '#', email: 'mailto:jonelle@projectmun.com' }
  },
  {
    name: 'Alvin Panganiban',
    role: 'Full Stack Developer',
    description: 'Versatile developer handling both frontend and backend with expertise in database management.',
    gradient: 'from-green-500 to-teal-500',
    initials: 'AP',
    socials: { linkedin: '#', github: '#', email: 'mailto:alvin@projectmun.com' }
  }
];

const AnimatedCounter = ({ target, suffix = '' }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          let start = 0;
          const duration = 2000;
          const increment = target / (duration / 16);

          const timer = setInterval(() => {
            start += increment;
            if (start >= target) {
              setCount(target);
              clearInterval(timer);
            } else {
              setCount(Math.floor(start));
            }
          }, 16);

          observer.disconnect();
        }
      },
      { threshold: 0.5 }
    );

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target]);

  return (
    <span ref={ref}>
      {count}{suffix}
    </span>
  );
};

const stats = [
  { value: 15, suffix: '+', label: 'Projects Completed' },
  { value: 4, suffix: '', label: 'Team Members' },
  { value: 100, suffix: '%', label: 'Client Satisfaction' },
  { value: 2, suffix: '+', label: 'Years Experience' }
];

const About = () => {
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  const values = [
    {
      icon: Target,
      title: 'Precision',
      description: 'We focus on delivering exactly what our clients need with attention to every detail.'
    },
    {
      icon: Zap,
      title: 'Innovation',
      description: 'We embrace cutting-edge technologies to create modern, future-proof solutions.'
    },
    {
      icon: Award,
      title: 'Quality',
      description: 'We never compromise on quality, ensuring robust and scalable applications.'
    },
    {
      icon: Users,
      title: 'Collaboration',
      description: 'We work closely with our clients, keeping communication transparent throughout.'
    }
  ];

  return (
    <section id="about" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-navy-900/50 to-transparent"></div>
      <div className="absolute -top-40 right-0 w-80 h-80 bg-blue-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-20 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Who We Are
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Meet the <span className="gradient-text">Team</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We are a passionate group of developers and designers dedicated to creating 
            exceptional digital experiences for businesses of all sizes.
          </p>
        </div>

        {/* Stats Section */}
        <div className="reveal mb-24">
          <div className="glass-dark rounded-3xl p-8 md:p-12">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              {stats.map((stat, index) => (
                <div key={index} className="text-center">
                  <div className="text-4xl md:text-5xl font-black gradient-text mb-2">
                    <AnimatedCounter target={stat.value} suffix={stat.suffix} />
                  </div>
                  <p className="text-gray-400 text-sm">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Team Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-24">
          {teamMembers.map((member, index) => (
            <div
              key={member.name}
              className="reveal group relative"
              style={{ transitionDelay: `${index * 100}ms` }}
            >
              <div className="glass-dark rounded-2xl p-6 card-hover glow-hover overflow-hidden h-full flex flex-col">
                {/* Gradient background on hover */}
                <div className={`absolute inset-0 bg-gradient-to-br ${member.gradient} opacity-0 group-hover:opacity-10 transition-opacity duration-500`}></div>

                {/* Avatar */}
                <div className={`w-20 h-20 rounded-2xl bg-gradient-to-br ${member.gradient} flex items-center justify-center mb-4 transform group-hover:scale-110 transition-transform duration-300 shadow-lg`}>
                  <span className="text-2xl font-bold text-white">{member.initials}</span>
                </div>

                <h3 className="text-xl font-bold text-white mb-1 group-hover:text-blue-400 transition-colors">
                  {member.name}
                </h3>
                <p className={`text-sm font-medium mb-3 bg-gradient-to-r ${member.gradient} bg-clip-text text-transparent`}>
                  {member.role}
                </p>
                <p className="text-gray-400 text-sm leading-relaxed flex-grow">
                  {member.description}
                </p>

                {/* Social Links */}
                <div className="flex gap-3 mt-4 pt-4 border-t border-white/10">
                  <a href={member.socials.linkedin} className="text-gray-400 hover:text-white transition-colors">
                    <Linkedin className="w-4 h-4" />
                  </a>
                  <a href={member.socials.github} className="text-gray-400 hover:text-white transition-colors">
                    <Github className="w-4 h-4" />
                  </a>
                  <a href={member.socials.email} className="text-gray-400 hover:text-white transition-colors">
                    <Mail className="w-4 h-4" />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Values Section */}
        <div className="reveal">
          <h3 className="text-3xl font-bold text-white text-center mb-12">
            Our <span className="gradient-text">Values</span>
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {values.map((value, index) => (
              <div
                key={value.title}
                className="glass rounded-xl p-6 text-center group hover:bg-white/10 transition-all duration-300"
                style={{ transitionDelay: `${index * 50}ms` }}
              >
                <div className="w-14 h-14 rounded-xl bg-blue-500/20 flex items-center justify-center mx-auto mb-4 group-hover:bg-blue-500/30 transition-colors">
                  <value.icon className="w-7 h-7 text-blue-400" />
                </div>
                <h4 className="text-lg font-semibold text-white mb-2">{value.title}</h4>
                <p className="text-gray-400 text-sm">{value.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;
